with feeders as (
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__PMASTERPOLICYNUMBER))) as HUB_POLICY_HK
        , cast(null as varchar) as TAX_HEAD_CODE
        , PSERVICETAX as TAX_AMOUNT
        , cast(null as varchar) as TAX_RATE
        , 'BJAZ_GENERIC_LOADER_LOG_TABLE' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_generic_loader_log_table') }}
    where (nullif(trim(PMASTERPOLICYNUMBER),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__REG_NO))) as HUB_POLICY_HK
        , cast(null as varchar) as TAX_HEAD_CODE
        , SBCESS_AMT as TAX_AMOUNT
        , cast(null as varchar) as TAX_RATE
        , 'BJAZ_GRP_HLT_MATERNITY_DTLS' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_grp_hlt_maternity_dtls') }}
    where (nullif(trim(REG_NO),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__CONTRACT_ID))) as HUB_POLICY_HK
        , cast(null as varchar) as TAX_HEAD_CODE
        , S_TAX as TAX_AMOUNT
        , cast(null as varchar) as TAX_RATE
        , 'BJAZ_ENROLL_SCR_DTLS' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_enroll_scr_dtls') }}
    where (nullif(trim(CONTRACT_ID),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__CONTRACT_ID))) as HUB_POLICY_HK
        , 'EDU_CESS' as TAX_HEAD_CODE
        , EDU_CESS as TAX_AMOUNT
        , cast(null as varchar) as TAX_RATE
        , 'BA_CCP_SUB_MATER_DTLS' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_ba_ccp_sub_mater_dtls') }}
    where (nullif(trim(CONTRACT_ID),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__CONTRACT_ID))) as HUB_POLICY_HK
        , 'JK_SURCHARGE_EDU_CESS' as TAX_HEAD_CODE
        , JK_SURCHG_EDUCESS_AMT as TAX_AMOUNT
        , cast(null as varchar) as TAX_RATE
        , 'BJAZ_POLICY_SUMMARY' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_policy_summary') }}
    where (nullif(trim(CONTRACT_ID),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__CONTRACT_ID))) as HUB_POLICY_HK
        , 'ST_EXP' as TAX_HEAD_CODE
        , ADJ_UTGST_AMT as TAX_AMOUNT
        , ST_EXP_RATE as TAX_RATE
        , 'BJAZ_POLICY_BASES_EXTN' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_policy_bases_extn') }}
    where (nullif(trim(CONTRACT_ID),'')) is not null
),

resolved as (
    select
        HUB_POLICY_HK,
        TAX_HEAD_CODE,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then TAX_AMOUNT end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then TAX_AMOUNT end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then TAX_AMOUNT end)) as TAX_AMOUNT,
        max(case when SOURCE_RUN = 'opus_health_delta3' then TAX_RATE end) as TAX_RATE,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_POLICY_HK, TAX_HEAD_CODE
),

hashed as (
    select
        *,
        case when TAX_HEAD_CODE is not null or TAX_AMOUNT is not null or TAX_RATE is not null
                     then md5(upper(coalesce(cast(TAX_HEAD_CODE as varchar), '') || '|' || coalesce(cast(TAX_AMOUNT as varchar), '') || '|' || coalesce(cast(TAX_RATE as varchar), '')))
                end as SAT_POLICY_TAX_HEAD_HASHDIFF
    from resolved
)

select * from hashed
where HUB_POLICY_HK is not null
  and SAT_POLICY_TAX_HEAD_HASHDIFF is not null
